/**
 *
 * AccordionIndicator is a component that displays an indicator inside an Accordion panel.
 *
 * [Live Demo](https://www.primereact.org/accordion/)
 *
 * @module AccordionIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { AccordionPanelInstance } from './AccordionPanel.types';
/**
 * Defines passthrough(pt) options type in AccordionIndicator component.
 */
export type AccordionIndicatorPassThroughType<E> = PassThroughType<AccordionIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of AccordionIndicator component.
 */
export interface AccordionIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: AccordionIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in AccordionIndicator component.
 */
export interface AccordionIndicatorProps extends BaseComponentProps<AccordionIndicatorInstance, unknown, AccordionIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the state of the accordion panel. Valid values are:
     * - "open": Indicator is visible when the panel is expanded.
     * - "closed": Indicator is visible when the panel is collapsed.
     */
    match?: 'open' | 'closed' | undefined;
}
/**
 * Defines valid state in AccordionIndicator component.
 */
export interface AccordionIndicatorState {
}
/**
 * Defines the methods and properties exposed by AccordionIndicator component.
 */
export interface AccordionIndicatorExposes {
    /**
     * The AccordionPanel component instance.
     */
    accordionpanel: AccordionPanelInstance | undefined | null;
}
/**
 * Instance of AccordionIndicator component.
 */
export type AccordionIndicatorInstance = ComponentInstance<AccordionIndicatorProps, AccordionIndicatorState, AccordionIndicatorExposes>;
